  box.addView(title("不可更改的规则"));LinearLayout fixed=card();fixed.addView(text("不受限应用：直接打开，不提问、不投入金币。",17,Color.BLACK));fixed.addView(text("不受限：电话、短信、通讯录、设置、系统界面/辅助功能、手机管家/安全、搜索、智能助理/语音助理、自带翻译/扫描、输入法、天气、健康、息屏/壁纸/背屏、笔记/备忘录、计算器、录音机、日历、时钟/闹钟、相机、文件管理、下载管理、高德地图、百度地图。",14,Color.DKGRAY));fixed.addView(text("受限：抖音/抖音极速版、快手/快手极速版、小红书、番茄系小说/七猫/起点、快看漫画/哔哩哔哩漫画、王者荣耀/和平精英/原神/元梦之星、斗鱼/虎牙、哔哩哔哩/腾讯视频/爱奇艺/优酷/芒果 TV/Netflix/YouTube、微博/知乎/贴吧/喜马拉雅/今日头条、淘宝/拼多多/得物/闲鱼。",14,Color.DKGRAY));fixed.addView(text("受限应用按预计时间预付；提前离开不退金币。到时可锁屏、回主屏幕或重新登记后继续。",14,Color.rgb(191,54,12)));box.addView(fixed);
  box.addView(title("其他应用"));LinearLayout rules=card();rules.addView(text("未列入固定名单的应用默认只提问、不扣金币；你可以将它们设为受限或明确设为免费。",14,Color.DKGRAY));rules.addView(button("自行设为受限  ·  "+validCustomSet(CUSTOM_LIMITED).size()+" 个",v->chooseApps(CUSTOM_LIMITED,"选择其他受限应用")));rules.addView(button("自行设为免费  ·  "+validCustomSet(CUSTOM_FREE).size()+" 个",v->chooseApps(CUSTOM_FREE,"选择其他免费应用")));box.addView(rules);
