 private String durationText(long ms){long minutes=Math.max(0,ms/60_000L);return minutes/60+" 小时 "+minutes%60+" 分钟";}
 private void chooseApps(String key,String heading){Intent x=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER);List<ResolveInfo> list=getPackageManager().queryIntentActivities(x,0);Collections.sort(list,new ResolveInfo.DisplayNameComparator(getPackageManager()));ArrayList<ResolveInfo> u=new ArrayList<>();HashSet<String>seen=new HashSet<>();for(ResolveInfo r:list){String pkg=r.activityInfo.packageName;if(seen.add(pkg)&&!pkg.equals(getPackageName())&&!FocusService.FIXED_FREE.contains(pkg)&&!FocusService.FIXED_LIMITED.contains(pkg))u.add(r);}String[] names=new String[u.size()];boolean[] checked=new boolean[u.size()];Set<String>cur=prefs.getStringSet(key,Collections.emptySet());for(int i=0;i<u.size();i++){names[i]=u.get(i).loadLabel(getPackageManager()).toString();checked[i]=cur.contains(u.get(i).activityInfo.packageName);}new AlertDialog.Builder(this).setTitle(heading).setMultiChoiceItems(names,checked,(d,which,isChecked)->checked[which]=isChecked).setNegativeButton("取消",null).setPositiveButton("完成",(d,w)->{Set<String>out=new HashSet<>();for(int i=0;i<checked.length;i++)if(checked[i])out.add(u.get(i).activityInfo.packageName);String other=key.equals(CUSTOM_LIMITED)?CUSTOM_FREE:CUSTOM_LIMITED;Set<String>opposite=new HashSet<>(prefs.getStringSet(other,Collections.emptySet()));opposite.removeAll(out);prefs.edit().putStringSet(key,new HashSet<>(out)).putStringSet(other,new HashSet<>(opposite)).apply();render();}).show();}
 private Set<String> validCustomSet(String key){Intent x=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER);Set<String>eligible=new HashSet<>();for(ResolveInfo r:getPackageManager().queryIntentActivities(x,0)){String pkg=r.activityInfo.packageName;if(!pkg.equals(getPackageName())&&!FocusService.FIXED_FREE.contains(pkg)&&!FocusService.FIXED_LIMITED.contains(pkg))eligible.add(pkg);}Set<String>result=new HashSet<>(prefs.getStringSet(key,Collections.emptySet()));result.retainAll(eligible);String other=key.equals(CUSTOM_FREE)?CUSTOM_LIMITED:CUSTOM_FREE;result.removeAll(prefs.getStringSet(other,Collections.emptySet()));return result;}
 private View protectionCheck(String label,String key,Runnable settings){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);CheckBox done=new CheckBox(this);done.setText(label);done.setTextSize(15);done.setChecked(prefs.getBoolean(key,false));done.setOnCheckedChangeListener((v,on)->prefs.edit().putBoolean(key,on).apply());row.addView(done,new LinearLayout.LayoutParams(0,-2,1));Button open=button("去设置",v->settings.run());row.addView(open,new LinearLayout.LayoutParams(dp(100),-2));return row;}
 private boolean hasUsageAccess(){AppOpsManager a=(AppOpsManager)getSystemService(APP_OPS_SERVICE);return a.checkOpNoThrow(AppOpsManager.OPSTR_GET_USAGE_STATS,android.os.Process.myUid(),getPackageName())==AppOpsManager.MODE_ALLOWED;} private boolean isAdmin(){return((DevicePolicyManager)getSystemService(DEVICE_POLICY_SERVICE)).isAdminActive(new ComponentName(this,FocusAdminReceiver.class));} private boolean hasAccessibility(){String enabled=Settings.Secure.getString(getContentResolver(),Settings.Secure.ENABLED_ACCESSIBILITY_SERVICES);return enabled!=null&&enabled.contains(getPackageName()+"/"+FocusAccessibilityService.class.getName());}
 private void requestBasics(){FocusService.start(this);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},8);} private void confirmBorrow(){int count=ledger.borrowCount();if(count>=2){Toast.makeText(this,"今日已借满 30 金币，明日 07:00 扣清 60 金币",Toast.LENGTH_LONG).show();return;}new AlertDialog.Builder(this).setTitle("借用 15 金币？").setMessage("立即到账 15；明日 07:00 必须偿还 30。今日最多借两次，所有待还金额会一次扣清，余额可能变为负数。").setNegativeButton("取消",null).setPositiveButton("确认借用",(d,w)->{if(!ledger.borrow(15))Toast.makeText(this,"今日已达借用上限",Toast.LENGTH_LONG).show();render();}).show();}
 private void enableAdmin(){startActivity(new Intent(DevicePolicyManager.ACTION_ADD_DEVICE_ADMIN).putExtra(DevicePolicyManager.EXTRA_DEVICE_ADMIN,new ComponentName(this,FocusAdminReceiver.class)).putExtra(DevicePolicyManager.EXTRA_ADD_EXPLANATION,"仅在预计时间到后选择锁屏时使用"));} private void enableOverlay(){startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));}
 private boolean batteryUnrestricted(){return((PowerManager)getSystemService(POWER_SERVICE)).isIgnoringBatteryOptimizations(getPackageName());} private void requestBatteryUnrestricted(){try{startActivity(new Intent(Settings.ACTION_REQUEST_IGNORE_BATTERY_OPTIMIZATIONS,Uri.parse("package:"+getPackageName())));}catch(Exception e){startActivity(new Intent(Settings.ACTION_IGNORE_BATTERY_OPTIMIZATION_SETTINGS));}}
 private void openAutostart(){try{Intent i=new Intent();i.setComponent(new ComponentName("com.miui.securitycenter","com.miui.permcenter.autostart.AutoStartManagementActivity"));startActivity(i);}catch(Exception e){startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName())));}}
 private void showRecentLockHelp(){new AlertDialog.Builder(this).setTitle("锁定后台任务").setMessage("打开最近任务，长按“专注金币”卡片，点击锁形图标。完成后，即使清理其他后台任务，小米系统也会尽量保留专注保护。\n\n系统的“强制停止”和关闭无障碍权限仍然可以终止应用，这是 Android 保留给手机所有者的控制权。").setNegativeButton("知道了",null).setPositiveButton("打开最近任务",(d,w)->{if(!FocusAccessibilityService.showRecents())Toast.makeText(this,"请先开启应用监听，然后手动打开最近任务",Toast.LENGTH_LONG).show();}).show();}
 private void exportData(){startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/json").putExtra(Intent.EXTRA_TITLE,"focus-coins-backup.json"),EXPORT);} private void importData(){startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("application/json"),IMPORT);}
 @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(c!=RESULT_OK||d==null)return;try{Uri u=d.getData();if(r==EXPORT){try(java.io.OutputStream o=getContentResolver().openOutputStream(u)){o.write(ledger.exportJson().getBytes(java.nio.charset.StandardCharsets.UTF_8));}}else if(r==IMPORT){String s;try(java.io.InputStream in=getContentResolver().openInputStream(u);java.util.Scanner z=new java.util.Scanner(in,"UTF-8").useDelimiter("\\A")){s=z.hasNext()?z.next():"";}Toast.makeText(this,ledger.importJson(s)?"导入成功":"文件格式不正确",Toast.LENGTH_SHORT).show();render();}}catch(Exception e){Toast.makeText(this,"操作失败："+e.getMessage(),Toast.LENGTH_LONG).show();}}
